<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { Activity, CheckCircle2, LoaderCircle, Search, TrendingUp } from "lucide-vue-next";
import { setPageMeta } from "@/lib/useRouteHead";
import { learningSessionRepository } from "@/data/repositories/learningSessionRepository";
import type { UiTutorStudent } from "@/data/models/learningSession";

setPageMeta({ title: "Student Insights — Teacher Workspace" });
const students = ref<UiTutorStudent[]>([]); const loading = ref(true); const error = ref(""); const search = ref("");
const filtered = computed(() => students.value.filter((student) => `${student.name} ${student.email} ${student.subjects.join(" ")}`.toLowerCase().includes(search.value.toLowerCase())));
onMounted(async () => { try { students.value = await learningSessionRepository.teacherStudents(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load granted students."; } finally { loading.value = false; } });
</script>
<template><div class="space-y-5"><div><p class="label-mono text-violet-600">Granted data only</p><h1 class="mt-1 text-[25px] font-bold">Student progress</h1><p class="mt-1 text-[13px] text-ink3">Daily activity, live sessions and readiness are calculated from persisted student sessions.</p></div><label class="flex max-w-sm items-center gap-2 rounded-xl border border-border bg-white px-3 py-2"><Search :size="15" class="text-ink4" /><input v-model="search" class="w-full bg-transparent text-[12px] outline-none" placeholder="Search granted students" /></label><div v-if="loading" class="grid place-items-center rounded-2xl border border-border bg-white py-20"><LoaderCircle class="animate-spin text-violet-600" /></div><p v-else-if="error" class="rounded-xl bg-red-50 p-4 text-[12px] text-red-700">{{ error }}</p><div v-else-if="!filtered.length" class="rounded-2xl border border-dashed border-border bg-white p-10 text-center text-[13px] text-ink3">No students are visible. Ask an administrator to grant a class, course, student or subject.</div><div v-else class="grid gap-4 lg:grid-cols-2"><article v-for="student in filtered" :key="student.userId" class="rounded-2xl border border-border bg-white p-5"><div class="flex items-start justify-between"><div><h2 class="text-[16px] font-bold">{{ student.name }}</h2><p class="text-[11px] text-ink3">{{ student.course || 'Course not set' }} · {{ student.subjects.join(', ') }}</p></div><strong class="text-[22px] text-violet-600">{{ student.progress.overallReadiness ?? '—' }}<span v-if="student.progress.overallReadiness !== null" class="text-[12px]">%</span></strong></div><div class="mt-4 grid grid-cols-3 gap-2"><div class="rounded-xl bg-violet-50 p-3"><Activity :size="15" class="text-violet-600" /><p class="mt-2 text-[10px] text-ink3">Active</p><strong>{{ student.progress.activeSessions.length }}</strong></div><div class="rounded-xl bg-emerald-50 p-3"><CheckCircle2 :size="15" class="text-emerald-600" /><p class="mt-2 text-[10px] text-ink3">Completed</p><strong>{{ student.progress.completedSessions.length }}</strong></div><div class="rounded-xl bg-blue-50 p-3"><TrendingUp :size="15" class="text-blue-600" /><p class="mt-2 text-[10px] text-ink3">Latest day</p><strong>{{ student.progress.dailyProgress[0]?.minutes || 0 }}m</strong></div></div><div v-if="student.progress.subjectReadiness.length" class="mt-4 space-y-2"><div v-for="subject in student.progress.subjectReadiness" :key="subject.subject"><div class="mb-1 flex justify-between text-[11px]"><span>{{ subject.subject }}</span><strong>{{ subject.readiness }}%</strong></div><div class="h-1.5 overflow-hidden rounded-full bg-bg-soft"><div class="h-full rounded-full bg-violet-500" :style="{ width: `${subject.readiness}%` }" /></div></div></div><div v-if="student.progress.activeSessions.length" class="mt-4 rounded-xl border border-violet-100 bg-violet-50 p-3"><p class="text-[10px] font-semibold uppercase tracking-wide text-violet-700">Currently active</p><p v-for="session in student.progress.activeSessions" :key="session.id" class="mt-1 text-[11px]">{{ session.subject }} · {{ session.topic || session.type }} · {{ Math.ceil(session.timeSeconds / 60) }} min</p></div></article></div></div></template>
